        for (a, b), (d, e) in zip(runs, runs[1:]):
            if d == b + 2 and row[b + 1] == 0:
                gap = b + 1
                for cc in range(a, e + 1):
                    out[r][cc] = color
                for rr in range(r):
                    out[rr][gap] = color
    return out
